from h34 import *
M=mcq;F=tf;S=short;N=num
# brick views
b='<text x="20" y="24" font-weight="bold">One brick, three views</text>'
b+='<rect x="30" y="50" width="160" height="70" fill="#e8b48c" stroke="#333" stroke-width="2"/><text x="30" y="140">Top view</text><text x="30" y="158" font-size="13">(long and wide)</text>'
b+='<rect x="260" y="50" width="160" height="40" fill="#e8b48c" stroke="#333" stroke-width="2"/><text x="260" y="140">Front view</text><text x="260" y="158" font-size="13">(long and tall)</text>'
b+='<rect x="500" y="50" width="70" height="40" fill="#e8b48c" stroke="#333" stroke-width="2"/><text x="500" y="140">Side view</text><text x="500" y="158" font-size="13">(wide and tall)</text>'
svgfile('c4-maths-brick-views.svg',640,175,b)
# 3x3 grid
b='<text x="10" y="22" font-weight="bold">Grid game: Rani gives clues</text>'
objs={(3,1):'pencil',(3,3):'eraser',(2,2):'apple',(3,2):'bottle',(1,1):'ball'}
for r in (1,2,3):
    for c in (1,2,3):
        x=90+(c-1)*110; y=40+(3-r)*70
        b+=f'<rect x="{x}" y="{y}" width="110" height="70" fill="#fff8e6" stroke="#333" stroke-width="2"/>'
        if (r,c) in objs: b+=f'<text x="{x+55}" y="{y+40}" text-anchor="middle">{objs[(r,c)]}</text>'
for c in (1,2,3): b+=f'<text x="{90+(c-1)*110+55}" y="270" text-anchor="middle" font-size="14">Column {c}</text>'
for r in (1,2,3): b+=f'<text x="10" y="{40+(3-r)*70+40}" font-size="14">Row {r}</text>'
svgfile('c4-maths-grid-game.svg',460,285,b)
chapter(4,'maths','hide-and-seek','Hide and Seek',
 ('Where are you hiding?','Mini, Bholu, Jagat and Rani are playing hide and seek. Jagat counts while the others go and hide. When he opens his eyes, what he can see depends on where he stands. Bholu even sees the tree from the top! In this chapter you will look at things from the top, the front and the side, find places on a grid, and read a map of a school.'),
 [('What can you see from where you stand?',['In hide and seek, what you can see depends on where you stand. Rani facing the hut cannot see who is hiding behind it.','If you look from a high place, you can see many more children than you can from the ground.','Bholu climbs up and sees the tree from the top, while Jagat clicks a picture of the same tree from the front. The two pictures look very different.']),
  ('Top view, front view and side view',['The same object looks different when we look from different places. We call these the top view, the front view and the side view.','Mini, Bholu and Rani each draw the same brick, but their drawings are different because each of them looked at it from a different side.','Looking from the top, a brick shows its long and wide face. From the front, we see the long and tall face. From the side, we see the wide and tall face.','A drawing from the top is the top view. A drawing from the front is the front view. A drawing from the side is the side view.','Try this with a chair, a table, a pencil, an eraser, a birthday cap or a bottle. A birthday cap looks like a triangle from the front and a circle from the top.']),
  ('Boxy buildings',['Jagat and Mini collect empty matchboxes and build different buildings. Then they draw each building from the front, the back and the top.','You can make your own buildings with empty boxes, draw the top, side and front views, and challenge a friend to match your drawing with the right building.']),
  ('Finding a place in a room',['Jagat\'s cat sits on the window and tries to find him. To tell the cat where Jagat sits, we say he is on the third desk in the first row.','We use the words row and column. Rows go across the room and columns go up and down.','To find an object, say its row first and then its desk. The notebook may be on the first desk of the second row. The apple you draw can go on the third desk of the second row.']),
  ('The grid game',['Bholu draws objects in a grid by following clues. A grid has rows and columns, and each box is where one row and one column meet.','The clues are: a ball at the bottom left corner, an eraser at the top right corner, a pencil at the top left corner, an apple in the middle of the second row and second column, and a water bottle in the third row and second column.','The first row is the bottom row and the first column is the left column. So the ball sits at row 1, column 1, which is the bottom left corner.','You can draw a grid on the floor or on your table and place objects on it to play with your partner.']),
  ('Treasure hunt on the grid',['In the treasure hunt, one player thinks of an object in a 4 by 4 grid and the other player finds it by moving step by step. You can move up, down, left or right, but never diagonally.','Mini takes 4 steps to the right of the starting point, then she gets clues like you are 3 steps away. She takes 2 steps left and 1 step up, and now she is still 2 steps away.','To describe a path say: from the starting point I moved 3 steps right, then 2 steps up. Then count all the steps to know the length of the path.','Two paths to the same object can have different lengths. The path with fewer steps is the shorter path.']),
  ('A map of the school',['Gyan has a drone that takes pictures from above. From the sky, the school looks green and beautiful, with walls of red bricks.','A sight map shows places the way a bird would see them from above. Preet\'s sister made a sight map of the school with the primary wing, the middle wing, the library, the playground, the stage, the IT room, the sports room, the MDM kitchen and the medical room.','To use a map, find where you are, find where you want to go, and follow a path. There can be many routes, and we can use different coloured pencils to trace each one.','The shortest route is the one with the fewest turns and steps. Use direction words such as turn left, turn right and go straight to explain it to someone.','Make your own sight map to show the way from your school entrance to your classroom and other important places.'])],
 [('On the grid, where does the pencil go? Clue: the pencil is in the top left corner of a 3 by 3 grid.',[('The top row is Row 3, and the left column is Column 1.','Find the row first and then the column.'),('So the pencil sits at Row 3, Column 1.','The corner where Row 3 and Column 1 meet.')]),
  ('A player starts at the bottom left corner. She moves 3 steps right and then 2 steps up. How many steps did she take in all, and where did she reach?',[('3 steps right plus 2 steps up.','Add the steps of each move.'),('3 + 2 = 5 steps.','The path is 5 steps long.'),('She is in the 4th column and the 3rd row, counting the start as column 1 and row 1.','Move 3 columns right and 2 rows up from the start.')]),
  ('A brick has a long side, a wide side and a tall side. Which view shows the long and wide face?',[('Looking at a brick from above, we see the long and wide face.','From above, we look at the flat top.'),('So the top view shows the long and wide face.','The front and side views show the tall side.')])],
 ('Explain what top view, front view and side view mean and how you would tell a friend the place of an object on a grid.',['Different sides give different views of the same object','Use rows and columns to say where something is','Move up, down, left or right, not diagonally','A map shows the way as seen from above'],['A top view and a side view look the same','You can move diagonally in the grid game']),
 ['An object looks different from the top, the front and the side.','Rows go across and columns go up and down; a place is told by its row and column.','On a grid we move up, down, left or right, one step at a time.','A sight map helps us find routes; the path with fewer steps is shorter.'],
 [M('1',1,'What do we call a view of an object seen from above?','Top view',[('Front view','That is seen from the front'),('Side view','That is seen from the side')],'A drawing made while looking down on the object is the top view.'),
  F('2',1,'The same brick can look different when it is seen from different sides.',True,'Each side shows a different face of the brick.'),
  M('3',1,'In the grid game, the ball is at the bottom left corner. In which row and column is it?','Row 1, Column 1',[('Row 3, Column 1','That is the top left corner'),('Row 1, Column 3','That is the bottom right corner')],'The first row is at the bottom and the first column is at the left.'),
  M('4',1,'Which moves are allowed in the grid treasure hunt?','Up, down, left and right',[('Diagonal moves','Diagonal moves are not allowed'),('Jumping over boxes','You must move one box at a time')],'Players move one box at a time up, down, left or right.'),
  N('5',2,'A player moves 3 steps right and then 2 steps up. How many steps did she move in all?',5,'3 steps + 2 steps = 5 steps.',[(6,'You multiplied instead of adding'),(1,'You subtracted instead of adding')]),
  M('6',2,'A birthday cap seen from the top looks like a ___.','circle',[('triangle','That is how it looks from the front'),('square','A cap does not look like a square')],'From the top you see the round base of the cap.'),
  M('7',2,'A map that shows places as seen from above is a ___ map.','sight',[('story','A story map is not a map of places'),('price','No such map')],'A sight map shows where places are from above.'),
  F('8',2,'In a classroom, rows go across the room and columns go up and down.',True,'We use rows and columns to find a desk.'),
  M('9',2,'Two paths lead to the same object. One takes 6 steps and the other takes 4 steps. Which is shorter?','The 4-step path',[('The 6-step path','It needs more steps'),('Both are equal','4 is less than 6')],'The path with fewer steps is shorter.'),
  S('10',3,'In the grid game where is the eraser if it is at the top right corner of a 3 by 3 grid? Write the row number.',['3','row 3','3rd row'],'The top row is Row 3 and the right column is Column 3.'),
  M('11',3,'Which view of a brick shows its long and tall face?','Front view',[('Top view','The top view shows the long and wide face'),('Bottom view','Not one of the three views in this chapter')],'From the front we see the long and tall face.'),
  F('12',3,'Rani cannot see the children hiding behind the hut if she faces the hut.',False,'She faces the hut, so she can see the children who hide near the front of the hut but not those at the back. Where you stand decides what you see.')],
 svgs=[('c4-maths-brick-views','Three rectangles show the top, front and side views of one brick.','The same brick looks different from the top, front and side.'),('c4-maths-grid-game','A 3 by 3 grid with a ball, a pencil, an eraser, an apple and a water bottle in their places.','Rows and columns tell the place of each object.')],
 keep=['top view','front view','grid','row','column'])
